// MIMEType returns the MIME type for a file extension (with or without leading dot),
// matching Rust FileType::from_str(ext).mime_type(). Returns "" when unknown.
func MIMEType(ext string) string {
	if len(ext) > 0 && ext[0] == '.' {
		ext = ext[1:]
	}
	return mimeByExtension[lowerASCII(ext)]
}

func lowerASCII(s string) string {
	b := []byte(s)
	for i, c := range b {
		if c >= 'A' && c <= 'Z' {
			b[i] = c + 32
		}
	}
	return string(b)
}
